import SwiftUI
import LarpModel

extension Provider {
    /// Fill behind the mark in app tiles.
    var tileColor: Color { self == .claude ? Color(red: 0.851, green: 0.467, blue: 0.341) : .black }
}

/// The provider's own mark, drawn as a template shape so it takes the
/// surrounding foreground style (and sidebar selection) like a symbol.
struct ProviderMark: Shape {
    let provider: Provider

    func path(in rect: CGRect) -> Path {
        let side = min(rect.width, rect.height)
        let origin = CGPoint(x: rect.midX - side / 2, y: rect.midY - side / 2)
        var path = Path(), op: Character = "M", number = "", values: [CGFloat] = [], started = false
        func point(_ i: Int) -> CGPoint { CGPoint(x: origin.x + values[i] * side, y: origin.y + values[i + 1] * side) }
        func flush() { if let value = Double(number) { values.append(value) }; number = "" }
        func emit() {
            switch op {
            case "M": path.move(to: point(0))
            case "L": path.addLine(to: point(0))
            case "C": path.addCurve(to: point(4), control1: point(0), control2: point(2))
            default: path.closeSubpath()
            }
            values.removeAll()
        }
        for character in provider == .claude ? Self.claude : Self.openAI {
            if character.isLetter { flush(); if started { emit() }; op = character; started = true }
            else if character == " " { flush() }
            else { number.append(character) }
        }
        flush(); emit()
        return path
    }

